frozen_ok()
images=[CAPTURE/f'page-{n:02}.png'for n in range(1,8)]
data,meta=decode(images);assert len(data)==5075 and meta['crc32']=='E51AB9FA'and meta['sha256']=='a6918841b5640347e2f139e46b37981a5fd2ea30ae860b4f2eecfe5c1090e9b7'
